const input=$json.body??$json;
const s=v=>String(v??'').trim();
const lower=v=>s(v).toLowerCase();
const leadId=s(input.lead_id??input.identity?.lead_id);
const propertyId=s(input.property_id??input.identity?.property_id);
const dealId=s(input.deal_id??input.identity?.deal_id);
const threadId=s(input.thread_id??input.identity?.thread_id);
const propertyType=lower(input.property_type??input.asset_type??input.property?.type);
const lifecycle=lower(input.lifecycle_state??input.lifecycle?.state);
const temperature=lower(input.temperature??input.lifecycle?.temperature);
const intent=lower(input.intent??input.seller_intent);
const motivation=lower(input.motivation??input.motivation_type);
const urgency=lower(input.urgency);
const sellerReply=s(input.seller_reply??input.inbound_message??input.message_text);
const dnc=input.dnc===true||input.dnc_suppressed===true||intent==='opt_out'||lifecycle==='suppressed';
const hasProperty=Boolean(propertyId||input.property?.address||input.property_address);
const valuation=Number.isFinite(Number(input.arv??input.market_value??input.estimated_market_value));
const comps=Array.isArray(input.comps)&&input.comps.length>0;
const repairs=Number.isFinite(Number(input.repairs??input.estimated_repairs));
const riskEvidence=Boolean(input.risk_evidence||input.property_risk||input.flood_zone||input.zoning);
const missing=[];
if(!leadId&&!dealId)missing.push('lead_id_or_deal_id');
if(!propertyId&&!hasProperty)missing.push('property_identity_or_address');
if(!propertyType)missing.push('property_type');
const engaged=temperature==='hot'||temperature==='warm'||intent==='positive_interest'||intent==='negotiation'||Boolean(sellerReply)||urgency==='high'||Boolean(motivation);
let status='not_ready',reason='insufficient seller/property evidence for underwriting';
if(dnc){status='suppressed';reason='DNC/opt-out prevents autonomous acquisition progression';}
else if(missing.length){status='needs_data';reason='required deal identity/property context is missing';}
else if(!engaged){status='monitor';reason='property exists but seller engagement does not yet justify underwriting spend';}
else{status='qualified';reason='seller engagement and property identity justify deal-level underwriting';}
const analysisRequestId='underwriting-request:'+(dealId||propertyId||leadId||threadId)+':v1';
const analysisRequest={request_id:analysisRequestId,lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,thread_id:threadId||null,property_type:propertyType||null,property_address:s(input.property_address??input.property?.address),seller:{intent:intent||null,motivation:motivation||null,urgency:urgency||null,reply_present:Boolean(sellerReply)},evidence:{arv_or_market_value:input.arv??input.market_value??input.estimated_market_value??null,repairs:input.repairs??input.estimated_repairs??null,comps:input.comps??[],risk_evidence:input.risk_evidence??null},policy:{economic_viability_primary:true,reference_70pct_secondary_only:true,property_type_specific_logic:true,no_inference:true}};
const nextWorkflow=status==='qualified'?'wf-069-deal-viability-mao-strategy-gate':status==='monitor'?'wf-099-seller-follow-up-timing-cadence':null;
return[{json:{ok:status!=='needs_data',qualification:{status,reason,score:status==='qualified'?82:status==='monitor'?50:0,engaged},analysis_request:status==='qualified'?analysisRequest:null,next:{workflow:nextWorkflow,action:status==='qualified'?'run_underwriting_and_mao_analysis':status==='monitor'?'continue_seller_follow_up':status==='suppressed'?'suppress_outreach':'collect_missing_deal_context'},requirements:{missing,available:{valuation,comps,repairs,risk_evidence}},identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,thread_id:threadId||null},dnc}}}];
